#include "../layered_mode/core.hpp"
#include <cassert>
#include <iostream>
#include <sstream>
using namespace layered;
Polygon rect(I a,I b,I c,I d){return {{a*Q,b*Q},{c*Q,b*Q},{c*Q,d*Q},{a*Q,d*Q}};}
Surface floor(std::string id,Polygon p,I z=0,I dx=0,I dy=0){Surface s;s.id=id;s.layer="layer";s.polygon=p;s.z=z;s.dx=dx;s.dy=dy;return s;}
std::string wire(const Map&m,const Config&c){std::ostringstream o;o<<std::string(64,'a')<<' '<<std::string(64,'b')<<' '<<c.radius<<' '<<c.height<<' '<<c.speed<<' '<<c.max_slope<<' '<<c.max_ticks<<' '<<c.start.x/Q<<' '<<c.start.y/Q<<' '<<c.surface;
 auto poly=[&](const Polygon&p){o<<' '<<p.size();for(auto v:p)o<<' '<<v.x/Q<<' '<<v.y/Q;};poly(m.boundary);o<<' '<<m.surfaces.size();for(auto&s:m.surfaces){o<<' '<<s.id<<' '<<s.layer<<' '<<s.z<<' '<<s.dx<<' '<<s.dy<<' '<<s.has_ceiling<<' '<<s.ceiling<<' '<<s.traversable;poly(s.polygon);}for(int k=0;k<2;++k){const auto&vs=k?m.triggers:m.solids;o<<' '<<vs.size();for(auto&v:vs){o<<' '<<v.id<<' '<<v.low<<' '<<v.high;poly(v.polygon);if(k){o<<' '<<v.scopes.size();for(auto s:v.scopes)o<<' '<<s;}}}o<<' '<<m.portals.size();for(auto&p:m.portals)o<<' '<<p.id<<' '<<p.from<<' '<<p.to<<' '<<p.a.x/Q<<' '<<p.a.y/Q<<' '<<p.b.x/Q<<' '<<p.b.y/Q<<' '<<p.bidirectional<<" 0";return o.str();}
Engine loaded(const Map&m,const Config&c){Engine e;std::istringstream in(wire(m,c));auto err=e.load(in);if(err)std::cerr<<*err<<'\n';assert(!err);return e;}
Map simple(){Map m;m.boundary=rect(0,0,10000,6000);m.surfaces.push_back(floor("floor",m.boundary));return m;}
Config cfg(){Config c;c.start={1000*Q,2000*Q};c.radius=100;c.height=300;c.speed=50;return c;}
int main(){
    {auto e=loaded(simple(),cfg());assert(!e.advance(10,1000,0));assert(e.position.x==1500*Q&&e.tick==10);auto h=e.hash();auto t=e.json();assert(e.advance(0,0,0));assert(e.advance(1,1001,0));assert(e.advance(1,0,0,0));assert(e.json()==t);assert(e.hash()==h);auto f=loaded(simple(),cfg());for(int i=0;i<10;++i)assert(!f.advance(1,1000,0));assert(f.hash()==h);}
    {auto m=simple();auto c=cfg();c.start={100*Q,100*Q};auto e=loaded(m,c);assert(!e.advance(5,1000,0));assert(e.position.x==350*Q&&e.position.y==100*Q);assert(!e.advance(10,-1000,0));assert(e.position.x==100*Q);assert(e.contacts[0].kind=="boundary");}
    {auto m=simple();m.solids.push_back({"thin",0,1000,rect(2020,0,2021,6000),{}});auto c=cfg();c.radius=1;c.start={2000*Q,2000*Q};auto e=loaded(m,c);assert(!e.advance(1,1000,0));assert(e.position.x<2019*Q);assert(e.contacts[0].id=="thin");}
    {auto m=simple();m.triggers.push_back({"thin_trigger",0,300,rect(2020,0,2021,6000),{0}});auto c=cfg();c.radius=1;c.start={2000*Q,2000*Q};auto e=loaded(m,c);assert(!e.advance(1,1000,0));assert(e.position.x==2050*Q);assert(e.events.size()==2&&e.events[0].type=="trigger_enter"&&e.events[1].type=="trigger_exit");assert(!e.active[0]);}
    {auto m=simple();m.surfaces={floor("west",rect(0,0,3000,6000)),floor("east",rect(3000,0,10000,6000))};m.portals.push_back({"gate",0,1,{3000*Q,0},{3000*Q,6000*Q},true});auto c=cfg();c.start={2500*Q,2000*Q};auto e=loaded(m,c);assert(!e.advance(20,1000,0));assert(e.surface==1&&e.position.x==3500*Q);assert(!e.advance(20,-1000,0));assert(e.surface==0&&e.position.x==2500*Q);m.portals[0].bidirectional=false;e=loaded(m,c);assert(!e.advance(20,1000,0));assert(!e.advance(30,-1000,0));assert(e.surface==1&&e.position.x==3000*Q);m.portals.clear();e=loaded(m,c);assert(!e.advance(20,1000,0));assert(e.surface==0&&e.position.x==2900*Q);}
    {auto m=simple();m.surfaces={floor("west",rect(0,0,2000,6000)),floor("ramp",rect(2000,0,6000,6000),-500,256),floor("deck",rect(6000,0,10000,6000),1000)};m.portals={{"bottom",0,1,{2000*Q,0},{2000*Q,6000*Q},true},{"top",1,2,{6000*Q,0},{6000*Q,6000*Q},true}};auto e=loaded(m,cfg());assert(!e.advance(120,1000,0));assert(e.surface==2&&e.position.x==7000*Q);assert(e.json().find("\"z_q1048576\":1048576000")!=std::string::npos);}
    {auto m=simple();m.surfaces.push_back(floor("upper",m.boundary,800));m.solids.push_back({"slab",700,800,m.boundary,{}});auto c=cfg();c.surface=1;auto e=loaded(m,c);assert(!e.advance(5,1000,0));assert(e.surface==1&&e.position.x==1250*Q);c.surface=0;c.height=700;auto old=e.json();std::istringstream bad(wire(m,c));assert(e.load(bad));assert(e.json()==old);}
    {auto m=simple();m.boundary=rect(-100000,-100000,100000,100000);m.surfaces={floor("diagonal",m.boundary,0,512,-512)};auto c=cfg();c.start={-99000*Q,-99000*Q};c.max_slope=1024;c.radius=1000;auto e=loaded(m,c);assert(!e.advance(600,1000,1000));assert(e.position.x==-69000*Q&&e.position.y==-69000*Q);}
    {auto m=simple();auto c=cfg();c.max_ticks=2;auto e=loaded(m,c);auto before=e.json();assert(e.advance(3,0,0));assert(e.json()==before);assert(!e.advance(2,0,0));before=e.json();assert(e.advance(1,0,0));assert(e.json()==before);assert(before.find("limit_reached")!=std::string::npos);}
    {auto m=simple();m.boundary={{0,0},{6000*Q,0},{0,8000*Q}};m.surfaces={floor("triangle",m.boundary)};auto c=cfg();c.start={1000*Q,1000*Q};auto e=loaded(m,c);assert(!e.advance(100,1000,0));assert(e.position.x==5125*Q&&e.position.y==1000*Q);assert(e.contacts[0].kind=="boundary");}
    {auto m=simple();m.solids.push_back({"triangle_solid",0,1000,{{2000*Q,1000*Q},{3000*Q,2000*Q},{2000*Q,3000*Q}}, {}});auto c=cfg();c.radius=1;c.start={2500*Q,1100*Q};auto e=loaded(m,c);assert(!e.advance(10,1000,0));assert(e.position.x==3000*Q);c.start={1500*Q,1100*Q};e=loaded(m,c);assert(!e.advance(20,1000,0));assert(e.position.x<1999*Q);}
    // A neighboring ceiling must name its declaring surface, not the current one.
    {auto m=simple();m.surfaces={floor("west",rect(0,0,3000,6000)),floor("east",rect(3000,0,10000,6000))};m.surfaces[1].has_ceiling=true;m.surfaces[1].ceiling=700;m.portals={{"gate",0,1,{3000*Q,0},{3000*Q,6000*Q},true}};auto c=cfg();c.start={2500*Q,2000*Q};c.height=700;auto e=loaded(m,c);assert(!e.advance(20,1000,0));assert(e.position.x==2900*Q&&e.surface==0);assert(e.contacts.size()==1&&e.contacts[0].kind=="ceiling"&&e.contacts[0].id=="east");}
    // Multiple violated declarations use authored order, independent of current support.
    {auto m=simple();m.surfaces={floor("east",rect(3000,0,5000,6000),-750,256),floor("west",rect(0,0,3000,6000))};for(auto&s:m.surfaces){s.has_ceiling=true;s.ceiling=700;}m.portals={{"gate",1,0,{3000*Q,0},{3000*Q,6000*Q},true}};auto c=cfg();c.surface=1;c.start={2800*Q,2000*Q};c.height=690;auto e=loaded(m,c);assert(!e.advance(20,1000,0));assert(e.position.x==2939*Q&&e.surface==1);assert(e.contacts.size()==2&&e.contacts[0].kind=="ceiling"&&e.contacts[1].kind=="ceiling");assert(e.contacts[0].id=="east"&&e.contacts[1].id=="west");m.surfaces[1].ceiling=701;e=loaded(m,c);assert(!e.advance(20,1000,0));assert(e.position.x==2939*Q&&e.contacts.size()==1&&e.contacts[0].id=="east");}
    // Direct native protocol independently rejects malformed profiles and preserves state.
    {auto m=simple();auto c=cfg();auto e=loaded(m,c);auto before=e.json();auto reject=[&](const Map&bad,const Config&badc){std::istringstream in(wire(bad,badc));assert(e.load(in));assert(e.json()==before);};auto bad=m;bad.surfaces[0].polygon[1]=bad.surfaces[0].polygon[0];reject(bad,c);bad=m;bad.surfaces[0].dx=1025;reject(bad,c);auto badc=c;badc.radius=0;reject(m,badc);bad=m;bad.surfaces.push_back(bad.surfaces[0]);reject(bad,c);std::istringstream extra(wire(m,c)+" extra");assert(e.load(extra));assert(e.json()==before);}
    // Deterministic property: arbitrary bounded actions keep the cylinder inside a flat convex domain.
    {auto m=simple();auto c=cfg();auto e=loaded(m,c),f=loaded(m,c);uint32_t rng=17;for(int i=0;i<2000;++i){rng=rng*1664525u+1013904223u;int dx=int(rng%2001)-1000;rng=rng*1664525u+1013904223u;int dy=int(rng%2001)-1000;assert(!e.advance(1,dx,dy));assert(!f.advance(1,dx,dy));assert(e.hash()==f.hash());assert(e.position.x>=100*Q&&e.position.x<=9900*Q&&e.position.y>=100*Q&&e.position.y<=5900*Q);}}
    std::cout<<"Layered native tests passed (15 groups, 2000 deterministic action pairs).\n";
}
